def _infosec_class(props) -> str:
    """approved / exception / denied / none (no value) / other (an old free-text value)."""
    raw = get_value(props or {}, INFOSEC_KEY)
    if raw is None:
        return "none"
    if raw == INFOSEC_APPROVED:
        return "approved"
    if raw == INFOSEC_EXCEPTION:
        return "exception"
    if raw == INFOSEC_DENIED:
        return "denied"
    return "other"


def _infosec_match(props, flt) -> bool:
    if not flt or flt == "all":
        return True
    if flt not in INFOSEC_FILTERS:
        raise HTTPException(status_code=400, detail="סטטוס אבטחת מידע לא מוכר")
    cls = _infosec_class(props)
    if flt == "approved_any":
        return cls in ("approved", "exception")
    return cls == flt


def _check_sort(sort, default):
    sort = sort or default
    if sort not in SORTS:
        raise HTTPException(status_code=400, detail="מיון לא מוכר")
    return sort


def report_infosec(db, date_from, date_to, project, infosec, sort):
    """One row per visitor, by information-security status; filter by status / project / approval date."""
    sort = _check_sort(sort, "project")
    if date_from and date_to and date_from > date_to:
        raise HTTPException(status_code=400, detail="'מתאריך' מאוחר מ'עד תאריך'")
    today = today_local()
    warn = get_int_setting(db, KEY_EXPIRY_DAYS, DEFAULT_EXPIRY_DAYS)
    ctx = InviterContext(db)
    items = []
    counts = {"approved": 0, "exception": 0, "denied": 0, "none": 0, "other": 0}
    for v in _visitors_in(db, project):
        props = v.properties or {}
        if not _infosec_match(props, infosec):
            continue
        d = parse_date(get_value(props, INFOSEC_EXPIRY_ALIASES))
        if (date_from or date_to) and d is None:
            continue
        if date_from and d < date_from:
            continue
        if date_to and d > date_to:
            continue
        cls = _infosec_class(props)
        counts[cls] += 1
        if d is None:
            days, label = None, ""
        else:
            days = (d - today).days
            label = STATUS_LABEL["expired" if days < 0 else ("expiring" if days <= warn else "ok")]
        items.append((v, cls, d, days, label, ctx.of(props)))
    if sort == "name":
        items.sort(key=lambda t: t[0].name or "")
    elif sort == "status":
        items.sort(key=lambda t: (_STATUS_RANK[t[1]], _project_order(_project_of(t[0])), t[0].name or ""))
    elif sort == "expiry":
        items.sort(key=lambda t: (t[3] is None, t[3] if t[3] is not None else 0, t[0].name or ""))
    else:
        items.sort(key=lambda t: (_project_order(_project_of(t[0])), t[0].name or ""))
    rows = [
        [
            v.name,
            v.visitorid,
            _project_of(v),
            get_value(v.properties or {}, INFOSEC_KEY) or "ללא סטטוס",
            dmy(d),
            days if days is not None else "",
            label,
            who,
        ]
        for v, _cls, d, days, label, who in items
    ]
    sub = ["נכון לתאריך: " + dmy(today), "אבטחת מידע: " + INFOSEC_FILTERS[infosec or "all"], "מיון: " + SORTS[sort]]
    if date_from or date_to:
        sub.append("תאריך תוקף האישור בין {} ל-{}".format(dmy(date_from) or "...", dmy(date_to) or "..."))
    if project:
        sub.append("פרויקט: " + project)
    sub.append(
        "בדוח: {} | מאושר {} | מאושר חריג {} | לא מאושר {} | ללא סטטוס {}{}".format(
            len(rows), counts["approved"], counts["exception"], counts["denied"], counts["none"],
            " | ערכים ישנים {}".format(counts["other"]) if counts["other"] else "",
        )
    )
    return {
        "title": TYPES["infosec"],
        "subtitle": sub,
        "columns": ["שם", "מספר זיהוי", "פרויקט", "אבטחת מידע", "תוקף אישור", "ימים לתוקף", "מצב תוקף", "מזמין"],
        "rows": rows,
    }


def report_infosec_summary(db, project):
    """Per project: how many visitors hold each information-security status."""
    acc: Dict[str, dict] = {}
    for v in _visitors_in(db, project):
        a = acc.setdefault(_project_of(v), {"approved": 0, "exception": 0, "denied": 0, "none": 0, "other": 0})
        a[_infosec_class(v.properties)] += 1
    rows = []
    tot = [0, 0, 0, 0, 0, 0]
    for p in sorted(acc, key=_project_order):
        a = acc[p]
        vals = [a["approved"], a["exception"], a["denied"], a["none"], a["other"], sum(a.values())]
        rows.append([p] + vals)
        tot = [x + y for x, y in zip(tot, vals)]
    if len(rows) > 1:
        rows.append(['סה"כ'] + tot)
    return {
        "title": TYPES["infosec_summary"],
        "subtitle": ["נכון לתאריך: " + dmy(today_local())] + (["פרויקט: " + project] if project else []),
        "columns": ["פרויקט", INFOSEC_APPROVED, INFOSEC_EXCEPTION, INFOSEC_DENIED, "ללא סטטוס", "ערך ישן אחר", 'סה"כ'],
        "rows": rows,
    }


